<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Falling Sand — Cellular Automata Sandbox</title>
<style>
  :root{
    --bg:#0b0d11;
    --panel:#161a21;
    --panel-2:#1e242e;
    --edge:#2b323d;
    --text:#e6e9ef;
    --muted:#8b93a1;
    --sand:#d9b46a;
    --water:#3b7fd4;
    --wall:#7c8390;
    --acid:#7fe04a;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    background:radial-gradient(1200px 700px at 50% -10%, #141a24 0%, var(--bg) 60%);
    color:var(--text);
    font:14px/1.45 ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:center;
    gap:16px;
    padding:24px 16px 32px;
    min-height:100%;
    -webkit-font-smoothing:antialiased;
  }
  header{text-align:center}
  h1{
    margin:0 0 4px;
    font-size:19px;
    font-weight:650;
    letter-spacing:.18em;
    text-transform:uppercase;
  }
  header p{margin:0;color:var(--muted);font-size:12.5px;letter-spacing:.04em}

  .stage{
    padding:10px;
    background:linear-gradient(180deg,var(--panel) 0%, #12161d 100%);
    border:1px solid var(--edge);
    border-radius:14px;
    box-shadow:0 18px 50px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.04);
  }
  #sand{
    display:block;
    width:480px;
    height:480px;
    max-width:82vmin;
    max-height:82vmin;
    background:#0d0f13;
    border-radius:8px;
    cursor:crosshair;
    touch-action:none;
    image-rendering:pixelated;
  }

  .toolbar{
    display:flex;
    flex-wrap:wrap;
    gap:8px;
    justify-content:center;
    align-items:center;
    max-width:520px;
  }
  button{
    appearance:none;
    display:inline-flex;
    align-items:center;
    gap:8px;
    padding:9px 14px;
    font:inherit;
    font-size:13px;
    font-weight:550;
    color:var(--text);
    background:var(--panel-2);
    border:1px solid var(--edge);
    border-radius:9px;
    cursor:pointer;
    transition:background .13s ease,border-color .13s ease,transform .08s ease;
  }
  button:hover{background:#262e3a;border-color:#3b4553}
  button:active{transform:translateY(1px)}
  button .swatch{
    width:12px;height:12px;border-radius:3px;
    box-shadow:inset 0 0 0 1px rgba(0,0,0,.35);
  }
  button.active{
    border-color:#5b6b85;
    background:#2c3646;
    box-shadow:0 0 0 1px rgba(120,160,220,.25), 0 0 14px rgba(80,130,200,.18);
  }
  #clear{color:#ffb4b4;border-color:#4a2b2f;background:#2a1b1e}
  #clear:hover{background:#3a2327;border-color:#66393e}

  .row2{display:flex;gap:14px;align-items:center;color:var(--muted);font-size:12px}
  .row2 label{display:flex;align-items:center;gap:7px}
  input[type=range]{width:120px;accent-color:#5b8fd6}
  .hint{color:#6c7484;font-size:11.5px;letter-spacing:.03em}
</style>
</head>
<body>

<header>
  <h1>Falling Sand</h1>
  <p>Drag on the canvas to paint · bottom-up cellular automata</p>
</header>

<div class="stage">
  <canvas id="sand" width="480" height="480"></canvas>
</div>

<div class="toolbar">
  <button id="mat-sand"  class="active" data-mat="sand"><span class="swatch" style="background:var(--sand)"></span>Sand</button>
  <button id="mat-water" data-mat="water"><span class="swatch" style="background:var(--water)"></span>Water</button>
  <button id="mat-wall"  data-mat="wall"><span class="swatch" style="background:var(--wall)"></span>Wall</button>
  <button id="mat-acid"  data-mat="acid"><span class="swatch" style="background:var(--acid)"></span>Acid</button>
  <button id="mat-empty" data-mat="empty"><span class="swatch" style="background:#0d0f13;box-shadow:inset 0 0 0 1px #3b4553"></span>Eraser</button>
  <button id="clear">Clear</button>
</div>

<div class="row2">
  <label>Brush <input id="brush" type="range" min="1" max="12" value="4"><span id="brushVal">4</span></label>
  <span class="hint">80×80+ grid · one cell per step</span>
</div>

<script>
(function () {
  "use strict";

  /* ------------------------------------------------------------------ *
   * Materials
   * ------------------------------------------------------------------ */
  var EMPTY = 0, SAND = 1, WATER = 2, WALL = 3, ACID = 4;

  var NAMES = ["empty", "sand", "water", "wall", "acid"];
  var IDS = { empty: EMPTY, sand: SAND, water: WATER, wall: WALL, acid: ACID };

  var W = 120, H = 120;                 // grid size in cells (>= 80x80)

  var grid = new Uint8Array(W * H);
  var moved = new Uint8Array(W * H);    // one move per particle per step

  function idx(x, y) { return y * W + x; }
  function inside(x, y) { return x >= 0 && x < W && y >= 0 && y < H; }
  function isLiquid(v) { return v === WATER || v === ACID; }

  /* Seeded PRNG so tick(n) is reproducible for tests. */
  var seed = 0x9e3779b9;
  function rnd() {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    var t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  }

  /* ------------------------------------------------------------------ *
   * Movement helpers
   * ------------------------------------------------------------------ */

  function moveTo(from, to, v) {
    grid[to] = v;
    grid[from] = EMPTY;
    moved[to] = 1;
  }

  /* Push a liquid at (lx,ly) OUT OF THE WAY — sideways or further down,
     never upward. Returns true if the liquid found somewhere to go.
     This is what keeps sand from "swapping" water up through a falling
     column: displaced liquid escapes locally, it can never ride up. */
  function displaceLiquid(lx, ly) {
    var self = idx(lx, ly);
    var v = grid[self];
    var first = rnd() < 0.5 ? -1 : 1;
    var cand = [
      [lx, ly + 1],                 // straight down (deeper)
      [lx + first, ly],             // sideways
      [lx - first, ly],
      [lx + first, ly + 1],         // diagonally down
      [lx - first, ly + 1]
    ];
    for (var i = 0; i < cand.length; i++) {
      var nx = cand[i][0], ny = cand[i][1];
      if (!inside(nx, ny)) continue;
      var t = idx(nx, ny);
      if (grid[t] === EMPTY && !moved[t]) {
        moveTo(self, t, v);
        return true;
      }
    }
    return false;
  }

  /* Sand: down, else down-diagonals (random order). Sinks through liquid
     only when that liquid has a local escape route. */
  function stepSand(x, y) {
    var self = idx(x, y);

    if (y + 1 < H) {
      var b = idx(x, y + 1);
      var bv = grid[b];
      if (bv === EMPTY) { moveTo(self, b, SAND); return; }
      if (isLiquid(bv) && !moved[b] && displaceLiquid(x, y + 1)) {
        moveTo(self, b, SAND); return;
      }
    }

    var first = rnd() < 0.5 ? -1 : 1;
    for (var i = 0; i < 2; i++) {
      var d = i === 0 ? first : -first;
      var nx = x + d, ny = y + 1;
      if (!inside(nx, ny)) continue;
      var t = idx(nx, ny);
      var tv = grid[t];
      if (tv === EMPTY) { moveTo(self, t, SAND); return; }
      if (isLiquid(tv) && !moved[t] && displaceLiquid(nx, ny)) {
        moveTo(self, t, SAND); return;
      }
    }
  }

  /* Water / acid: fall, else fall diagonally, else spread sideways. */
  function stepLiquid(x, y, v) {
    var self = idx(x, y);

    if (y + 1 < H) {
      var b = idx(x, y + 1);
      if (grid[b] === EMPTY) { moveTo(self, b, v); return; }
    }

    var first = rnd() < 0.5 ? -1 : 1;
    var i, d, nx, t;

    for (i = 0; i < 2; i++) {
      d = i === 0 ? first : -first;
      nx = x + d;
      if (!inside(nx, y + 1)) continue;
      t = idx(nx, y + 1);
      if (grid[t] === EMPTY) { moveTo(self, t, v); return; }
    }

    for (i = 0; i < 2; i++) {
      d = i === 0 ? first : -first;
      nx = x + d;
      if (!inside(nx, y)) continue;
      t = idx(nx, y);
      if (grid[t] === EMPTY && !moved[t]) { moveTo(self, t, v); return; }
    }
  }

  /* Acid corrodes sand/wall below or beside it. Returns true if the acid
     cell itself was consumed. */
  function acidCorrode(x, y) {
    var targets = [];
    var probe = [[x, y + 1], [x - 1, y], [x + 1, y]];
    for (var i = 0; i < probe.length; i++) {
      var nx = probe[i][0], ny = probe[i][1];
      if (!inside(nx, ny)) continue;
      var v = grid[idx(nx, ny)];
      if (v === SAND || v === WALL) targets.push(idx(nx, ny));
    }
    if (!targets.length) return false;
    if (rnd() > 0.25) return false;                 // slow, satisfying erosion

    var pick = targets[(rnd() * targets.length) | 0];
    grid[pick] = EMPTY;
    moved[pick] = 1;
    if (rnd() < 0.5) { grid[idx(x, y)] = EMPTY; return true; }  // acid spent
    return false;
  }

  /* ------------------------------------------------------------------ *
   * One simulation step — strictly bottom row upward.
   * ------------------------------------------------------------------ */
  function step() {
    moved.fill(0);

    for (var y = H - 1; y >= 0; y--) {
      var l2r = rnd() < 0.5;
      for (var k = 0; k < W; k++) {
        var x = l2r ? k : W - 1 - k;
        var self = idx(x, y);
        var v = grid[self];
        if (v === EMPTY || v === WALL) continue;
        if (moved[self]) continue;

        if (v === ACID) {
          if (acidCorrode(x, y)) continue;
          if (grid[self] !== ACID) continue;
        }

        if (v === SAND) stepSand(x, y);
        else stepLiquid(x, y, v);
      }
    }
  }

  /* ------------------------------------------------------------------ *
   * Rendering
   * ------------------------------------------------------------------ */
  var canvas = document.getElementById("sand");
  var ctx = canvas.getContext("2d");
  ctx.imageSmoothingEnabled = false;

  var buf = document.createElement("canvas");
  buf.width = W; buf.height = H;
  var bctx = buf.getContext("2d");
  var img = bctx.createImageData(W, H);
  var px = img.data;

  var PAL = [
    [13, 15, 19],     // empty
    [217, 180, 106],  // sand
    [59, 127, 212],   // water
    [124, 131, 144],  // wall
    [127, 224, 74]    // acid
  ];
  /* Per-cell tint so piles read as grains, not flat blocks. */
  var tint = new Int8Array(W * H);
  for (var i = 0; i < tint.length; i++) tint[i] = ((rnd() * 22) | 0) - 11;

  function draw() {
    for (var i = 0, p = 0; i < grid.length; i++, p += 4) {
      var c = PAL[grid[i]];
      var t = grid[i] === EMPTY ? 0 : tint[i];
      px[p]     = c[0] + t;
      px[p + 1] = c[1] + t;
      px[p + 2] = c[2] + t;
      px[p + 3] = 255;
    }
    bctx.putImageData(img, 0, 0);
    ctx.imageSmoothingEnabled = false;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(buf, 0, 0, canvas.width, canvas.height);
  }

  function loop() {
    step();
    draw();
    requestAnimationFrame(loop);
  }

  /* ------------------------------------------------------------------ *
   * Painting
   * ------------------------------------------------------------------ */
  var current = SAND;
  var brush = 4;
  var painting = false;
  var lastX = null, lastY = null;

  function cellFromEvent(e) {
    var r = canvas.getBoundingClientRect();
    return {
      x: Math.floor((e.clientX - r.left) / r.width * W),
      y: Math.floor((e.clientY - r.top) / r.height * H)
    };
  }

  function paint(cx, cy) {
    var rad = brush - 1;
    for (var dy = -rad; dy <= rad; dy++) {
      for (var dx = -rad; dx <= rad; dx++) {
        if (dx * dx + dy * dy > rad * rad + rad) continue;
        var x = cx + dx, y = cy + dy;
        if (!inside(x, y)) continue;
        if (current === EMPTY || current === WALL || rnd() < 0.85) {
          grid[idx(x, y)] = current;
        }
      }
    }
  }

  /* Interpolate along the drag so fast strokes stay continuous. */
  function paintLine(x0, y0, x1, y1) {
    var n = Math.max(Math.abs(x1 - x0), Math.abs(y1 - y0));
    if (n === 0) { paint(x1, y1); return; }
    for (var i = 0; i <= n; i++) {
      paint(Math.round(x0 + (x1 - x0) * i / n), Math.round(y0 + (y1 - y0) * i / n));
    }
  }

  canvas.addEventListener("pointerdown", function (e) {
    painting = true;
    canvas.setPointerCapture(e.pointerId);
    var c = cellFromEvent(e);
    lastX = c.x; lastY = c.y;
    paint(c.x, c.y);
    e.preventDefault();
  });
  canvas.addEventListener("pointermove", function (e) {
    if (!painting) return;
    var c = cellFromEvent(e);
    paintLine(lastX, lastY, c.x, c.y);
    lastX = c.x; lastY = c.y;
    e.preventDefault();
  });
  function endPaint() { painting = false; lastX = lastY = null; }
  canvas.addEventListener("pointerup", endPaint);
  canvas.addEventListener("pointercancel", endPaint);
  window.addEventListener("blur", endPaint);

  /* Mouse fallback for harnesses that dispatch legacy mouse events. */
  canvas.addEventListener("mousedown", function (e) {
    if (painting) return;
    painting = true;
    var c = cellFromEvent(e);
    lastX = c.x; lastY = c.y;
    paint(c.x, c.y);
  });
  canvas.addEventListener("mousemove", function (e) {
    if (!painting) return;
    var c = cellFromEvent(e);
    paintLine(lastX, lastY, c.x, c.y);
    lastX = c.x; lastY = c.y;
  });
  window.addEventListener("mouseup", endPaint);

  /* ------------------------------------------------------------------ *
   * Controls
   * ------------------------------------------------------------------ */
  var matButtons = Array.prototype.slice.call(document.querySelectorAll("[data-mat]"));
  matButtons.forEach(function (b) {
    b.addEventListener("click", function () {
      current = IDS[b.getAttribute("data-mat")];
      matButtons.forEach(function (o) { o.classList.toggle("active", o === b); });
    });
  });

  function clearGrid() { grid.fill(EMPTY); moved.fill(0); }
  document.getElementById("clear").addEventListener("click", clearGrid);

  var brushInput = document.getElementById("brush");
  var brushVal = document.getElementById("brushVal");
  brushInput.addEventListener("input", function () {
    brush = parseInt(brushInput.value, 10);
    brushVal.textContent = brushInput.value;
  });

  /* ------------------------------------------------------------------ *
   * Programmatic API
   * ------------------------------------------------------------------ */
  window.sim = {
    w: W,
    h: H,
    tick: function (n) {
      n = (n === undefined) ? 1 : (n | 0);
      for (var i = 0; i < n; i++) step();
      draw();
    },
    get: function (x, y) {
      x |= 0; y |= 0;
      if (!inside(x, y)) return "wall";
      return NAMES[grid[idx(x, y)]];
    },
    set: function (x, y, material) {
      x |= 0; y |= 0;
      if (!inside(x, y)) return;
      var m = IDS[material];
      if (m === undefined) return;
      grid[idx(x, y)] = m;
      moved[idx(x, y)] = 0;
    },
    clear: clearGrid
  };

  /* A little starter scene. */
  (function seedScene() {
    for (var x = 30; x < 90; x++) {
      for (var y = 96; y < 112; y++) grid[idx(x, y)] = WATER;
    }
    for (var x2 = 24; x2 < 96; x2++) grid[idx(x2, 112)] = WALL;
    for (var y2 = 96; y2 < 112; y2++) { grid[idx(24, y2)] = WALL; grid[idx(95, y2)] = WALL; }
  })();

  draw();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
